CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE organization (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL);
CREATE TABLE venue (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organization, name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Kolkata', currency text NOT NULL DEFAULT 'INR' CHECK(length(currency)=3), day_cutoff integer NOT NULL DEFAULT 0 CHECK(day_cutoff BETWEEN 0 AND 23), token_prefix text NOT NULL DEFAULT 'A', menu_version integer NOT NULL DEFAULT 1, refund_limit bigint NOT NULL DEFAULT 0 CHECK(refund_limit>=0), refund_daily_limit bigint NOT NULL DEFAULT 0 CHECK(refund_daily_limit>=0), active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1);
CREATE TABLE outlet (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), venue_id uuid NOT NULL REFERENCES venue, name text NOT NULL, cuisine text NOT NULL, collection_point text NOT NULL DEFAULT 'Main counter', active boolean NOT NULL DEFAULT true, default_station_id uuid, version integer NOT NULL DEFAULT 1, UNIQUE(id,venue_id));
CREATE TABLE station (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), outlet_id uuid NOT NULL REFERENCES outlet, name text NOT NULL, kind text NOT NULL CHECK(kind IN ('PREP','QUICK_SERVICE')), active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, UNIQUE(id,outlet_id));
ALTER TABLE outlet ADD CONSTRAINT default_station_fk FOREIGN KEY(default_station_id,id) REFERENCES station(id,outlet_id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE app_user (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organization, email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE role_assignment (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES app_user, venue_id uuid NOT NULL REFERENCES venue, outlet_id uuid REFERENCES outlet, station_id uuid REFERENCES station, role text NOT NULL CHECK(role IN ('SUPER_ADMIN','OWNER','MANAGER','BILLING','COOK','SERVER','KIOSK','DISPLAY')), capabilities text[] NOT NULL DEFAULT '{}');
CREATE TABLE session (id_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES app_user, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE device (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), venue_id uuid NOT NULL REFERENCES venue, name text NOT NULL, kind text NOT NULL CHECK(kind IN ('POS','KIOSK','KITCHEN','SERVING','DISPLAY')), active boolean NOT NULL DEFAULT true, credential_hash text, last_seen_at timestamptz, version integer NOT NULL DEFAULT 1);
CREATE TABLE category (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), outlet_id uuid NOT NULL REFERENCES outlet, name text NOT NULL, station_id uuid REFERENCES station, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1);
CREATE TABLE menu_item (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), outlet_id uuid NOT NULL REFERENCES outlet, category_id uuid REFERENCES category, station_id uuid, name text NOT NULL, description text NOT NULL DEFAULT '', image_url text NOT NULL DEFAULT '/images/placeholder.svg', image_alt text NOT NULL DEFAULT 'Menu item', price_minor bigint NOT NULL CHECK(price_minor>=0), tax_bps integer NOT NULL DEFAULT 0 CHECK(tax_bps BETWEEN 0 AND 10000), tax_inclusive boolean NOT NULL DEFAULT true, allergens text NOT NULL DEFAULT '', dietary text NOT NULL DEFAULT 'Vegetarian', published boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, FOREIGN KEY(station_id,outlet_id) REFERENCES station(id,outlet_id));
CREATE TABLE variant (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL REFERENCES menu_item, name text NOT NULL, price_minor bigint CHECK(price_minor>=0), station_id uuid REFERENCES station, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1);
CREATE TABLE modifier_group (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL REFERENCES menu_item, name text NOT NULL, min_select integer NOT NULL DEFAULT 0, max_select integer NOT NULL DEFAULT 1, CHECK(min_select>=0 AND max_select>=min_select));
CREATE TABLE modifier_option (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES modifier_group, name text NOT NULL, price_minor bigint NOT NULL DEFAULT 0 CHECK(price_minor>=0));
CREATE TABLE operating_schedule (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), outlet_id uuid NOT NULL REFERENCES outlet, day integer NOT NULL CHECK(day BETWEEN 0 AND 6), opens time NOT NULL, closes time NOT NULL, CHECK(opens<closes));
CREATE TABLE availability_hold (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), venue_id uuid NOT NULL REFERENCES venue, outlet_id uuid NOT NULL REFERENCES outlet, station_id uuid REFERENCES station, item_id uuid REFERENCES menu_item, actor_id uuid NOT NULL REFERENCES app_user, reason text NOT NULL, expires_at timestamptz, released_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quote (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), venue_id uuid NOT NULL REFERENCES venue, actor_id uuid NOT NULL REFERENCES app_user, device_id uuid NOT NULL REFERENCES device, channel text NOT NULL CHECK(channel IN ('POS','KIOSK')), alias text NOT NULL, menu_version integer NOT NULL, units jsonb NOT NULL, total_minor bigint NOT NULL CHECK(total_minor>=0), discount_minor bigint NOT NULL DEFAULT 0, currency text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_order (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), venue_id uuid NOT NULL REFERENCES venue, actor_id uuid NOT NULL REFERENCES app_user, device_id uuid NOT NULL REFERENCES device, quote_id uuid NOT NULL UNIQUE REFERENCES quote, checkout_key text NOT NULL UNIQUE, channel text NOT NULL, alias text NOT NULL, currency text NOT NULL, total_minor bigint NOT NULL CHECK(total_minor>=0), status text NOT NULL DEFAULT 'PENDING', token_seq integer, business_date date, tracking_hash text NOT NULL, tracking_expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', pickup_hash text NOT NULL, paid_at timestamptz, lease_expires_at timestamptz NOT NULL, dispatched_at timestamptz, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(venue_id,business_date,token_seq));
CREATE TABLE outlet_suborder (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES customer_order, outlet_id uuid NOT NULL REFERENCES outlet, UNIQUE(order_id,outlet_id));
CREATE TABLE station_ticket (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES customer_order, outlet_id uuid NOT NULL REFERENCES outlet, station_id uuid NOT NULL, route_version integer NOT NULL, FOREIGN KEY(station_id,outlet_id) REFERENCES station(id,outlet_id), UNIQUE(order_id,station_id,route_version));
CREATE TABLE order_line (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), suborder_id uuid NOT NULL REFERENCES outlet_suborder, item_id uuid NOT NULL REFERENCES menu_item, snapshot jsonb NOT NULL, quantity integer NOT NULL CHECK(quantity>0));
CREATE TABLE work_unit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), line_id uuid NOT NULL REFERENCES order_line, order_id uuid NOT NULL REFERENCES customer_order, outlet_id uuid NOT NULL REFERENCES outlet, station_id uuid NOT NULL, ticket_id uuid NOT NULL REFERENCES station_ticket, ordinal integer NOT NULL, name text NOT NULL, modifiers text NOT NULL DEFAULT '', amount_minor bigint NOT NULL CHECK(amount_minor>=0), gross_minor bigint NOT NULL CHECK(gross_minor>=0), discount_minor bigint NOT NULL DEFAULT 0, tax_minor bigint NOT NULL DEFAULT 0, prep_state text NOT NULL DEFAULT 'RECEIVED' CHECK(prep_state IN ('RECEIVED','ACKNOWLEDGED','PREPARING','COMPLETED')), serve_state text NOT NULL DEFAULT 'WAITING' CHECK(serve_state IN ('WAITING','READY_FOR_PICKUP','HANDED_OVER')), cancel_state text NOT NULL DEFAULT 'ACTIVE' CHECK(cancel_state IN ('ACTIVE','CANCEL_REQUESTED','CANCELLED')), started_at timestamptz, completed_at timestamptz, ready_at timestamptz, handed_at timestamptz, version integer NOT NULL DEFAULT 1, rework_of uuid REFERENCES work_unit, FOREIGN KEY(station_id,outlet_id) REFERENCES station(id,outlet_id), UNIQUE(line_id,ordinal));
CREATE INDEX work_queue ON work_unit(station_id,prep_state,order_id);
CREATE INDEX serving_queue ON work_unit(outlet_id,serve_state);
CREATE TABLE token_counter (venue_id uuid REFERENCES venue, business_date date, next_value integer NOT NULL, PRIMARY KEY(venue_id,business_date));
CREATE TABLE cash_shift (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), venue_id uuid NOT NULL REFERENCES venue, device_id uuid NOT NULL REFERENCES device, actor_id uuid NOT NULL REFERENCES app_user, float_minor bigint NOT NULL CHECK(float_minor>=0), counted_minor bigint, variance_minor bigint, opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE UNIQUE INDEX one_open_shift ON cash_shift(device_id) WHERE closed_at IS NULL;
CREATE TABLE cash_movement (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shift_id uuid NOT NULL REFERENCES cash_shift, amount_minor bigint NOT NULL, reason text NOT NULL, actor_id uuid NOT NULL REFERENCES app_user, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_intent (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL UNIQUE REFERENCES customer_order, amount_minor bigint NOT NULL CHECK(amount_minor>=0), tender text NOT NULL CHECK(tender IN ('CASH','DIGITAL','ZERO')), status text NOT NULL DEFAULT 'PENDING', operation_key text NOT NULL UNIQUE, provider_ref text UNIQUE, shift_id uuid REFERENCES cash_shift, received_minor bigint, change_minor bigint, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE capture (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intent_id uuid NOT NULL REFERENCES payment_intent, provider_ref text NOT NULL UNIQUE, amount_minor bigint NOT NULL CHECK(amount_minor>=0), confirmed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refund_request (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES customer_order, capture_id uuid NOT NULL REFERENCES capture, requested_by uuid NOT NULL REFERENCES app_user, approved_by uuid REFERENCES app_user, mode text NOT NULL CHECK(mode IN ('CANCEL_AND_REFUND','REFUND_ONLY')), amount_minor bigint NOT NULL CHECK(amount_minor>0), reason_code text NOT NULL, note text NOT NULL, status text NOT NULL DEFAULT 'APPROVAL_REQUIRED', operation_key text NOT NULL UNIQUE, provider_ref text UNIQUE, policy jsonb NOT NULL, decision_note text, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), succeeded_at timestamptz);
CREATE TABLE refund_allocation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), refund_id uuid NOT NULL REFERENCES refund_request, unit_id uuid NOT NULL REFERENCES work_unit, amount_minor bigint NOT NULL CHECK(amount_minor>0), tax_minor bigint NOT NULL DEFAULT 0, UNIQUE(refund_id,unit_id));
CREATE INDEX refund_queue ON refund_request(status,updated_at);
CREATE TABLE journal_transaction (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), venue_id uuid NOT NULL REFERENCES venue, source_key text NOT NULL UNIQUE, description text NOT NULL, currency text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE journal_line (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id uuid NOT NULL REFERENCES journal_transaction, outlet_id uuid REFERENCES outlet, account text NOT NULL, debit_minor bigint NOT NULL DEFAULT 0, credit_minor bigint NOT NULL DEFAULT 0, CHECK((debit_minor>0 AND credit_minor=0) OR (credit_minor>0 AND debit_minor=0)));
CREATE FUNCTION ensure_balanced() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (SELECT coalesce(sum(debit_minor-credit_minor),0) FROM journal_line WHERE transaction_id=NEW.transaction_id)<>0 THEN RAISE EXCEPTION 'Unbalanced journal'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER balanced_journal AFTER INSERT ON journal_line DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ensure_balanced();
CREATE TABLE audit_event (id bigserial PRIMARY KEY, venue_id uuid NOT NULL REFERENCES venue, outlet_id uuid REFERENCES outlet, actor_id uuid REFERENCES app_user, action text NOT NULL, resource_id text NOT NULL, details jsonb NOT NULL DEFAULT '{}', request_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_scope ON audit_event(venue_id,outlet_id,id);
CREATE FUNCTION immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Append-only record'; END $$;
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_event FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_journal BEFORE UPDATE OR DELETE ON journal_line FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_transaction BEFORE UPDATE OR DELETE ON journal_transaction FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TABLE outbox (id bigserial PRIMARY KEY, event_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, venue_id uuid NOT NULL REFERENCES venue, outlet_id uuid REFERENCES outlet, order_id uuid REFERENCES customer_order, type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_inbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, event_id text NOT NULL, payload jsonb NOT NULL, processed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,event_id));
CREATE TABLE idempotency_record (principal_id uuid NOT NULL REFERENCES app_user, endpoint text NOT NULL, key text NOT NULL, request_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(principal_id,endpoint,key));
CREATE TABLE provider_operation (operation_key text PRIMARY KEY, kind text NOT NULL, amount_minor bigint NOT NULL, provider_ref text NOT NULL UNIQUE, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE provider_record (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), venue_id uuid NOT NULL REFERENCES venue, external_id text NOT NULL, kind text NOT NULL CHECK(kind IN ('CAPTURE','REFUND','FEE','SETTLEMENT')), amount_minor bigint NOT NULL CHECK(amount_minor>=0), currency text NOT NULL, reference text NOT NULL, evidence_hash text NOT NULL, matched boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(venue_id,external_id));
CREATE TABLE reconciliation_case (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL UNIQUE REFERENCES provider_record, venue_id uuid NOT NULL REFERENCES venue, reason text NOT NULL, status text NOT NULL DEFAULT 'OPEN', resolution text, resolved_by uuid REFERENCES app_user, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settlement_batch (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), venue_id uuid NOT NULL REFERENCES venue, outlet_id uuid NOT NULL REFERENCES outlet, amount_minor bigint NOT NULL CHECK(amount_minor>0), status text NOT NULL DEFAULT 'DRAFT', created_by uuid NOT NULL REFERENCES app_user, approved_by uuid REFERENCES app_user, bank_reference text UNIQUE, cutoff_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX active_outlet_batch ON settlement_batch(outlet_id) WHERE status IN ('DRAFT','APPROVED');
CREATE TABLE print_job (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES customer_order, actor_id uuid NOT NULL REFERENCES app_user, copy boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'PENDING', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE incident (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), venue_id uuid NOT NULL REFERENCES venue, outlet_id uuid NOT NULL REFERENCES outlet, order_id uuid REFERENCES customer_order, actor_id uuid NOT NULL REFERENCES app_user, reason text NOT NULL, status text NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now());
